import{_ as a,o as f,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"الطوارئ والأرقام المهمة","description":"بمن تتصل في قطر عند الحاجة إلى الشرطة أو الدفاع المدني أو الإسعاف أو عند انقطاع الكهرباء والماء، وماذا تقول، وخدمة الصم، وما تفعله بعد حادث مروري بسيط.","frontmatter":{"title":"الطوارئ والأرقام المهمة","description":"بمن تتصل في قطر عند الحاجة إلى الشرطة أو الدفاع المدني أو الإسعاف أو عند انقطاع الكهرباء والماء، وماذا تقول، وخدمة الصم، وما تفعله بعد حادث مروري بسيط.","lastChecked":"2026-10","sourceCount":11},"headers":[],"relativePath":"ar/guide/emergencies.md","filePath":"ar/guide/emergencies.md"}'),s={name:"ar/guide/emergencies.md"};function t(n,e,l,i,c,p){return f(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="الطوارئ-والأرقام-المهمة" tabindex="-1">الطوارئ والأرقام المهمة <a class="header-anchor" href="#الطوارئ-والأرقام-المهمة" aria-label="Permalink to &quot;الطوارئ والأرقام المهمة&quot;">​</a></h1><p>في حالات الطوارئ اتصل بالرقم 999. احفظ الأرقام الواردة في هذه الصفحة في هاتفك الآن، وعلّمها لأفراد أسرتك.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="الرقم-999" tabindex="-1">الرقم 999 <a class="header-anchor" href="#الرقم-999" aria-label="Permalink to &quot;الرقم 999&quot;">​</a></h2><p>يستقبل قسم خدمات الطوارئ في وزارة الداخلية بلاغات الجرائم والحرائق والحالات الطبية الطارئة على الرقم 999 على مدار الساعة. ويضم القسم مترجمين لعدة لغات منها الإنجليزية والفرنسية والصينية والفلبينية والأردية.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> كما يحيل بلاغات الحوادث إلى الجهات المختصة.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><p>عند الاتصال اذكر اسمك ورقم هاتفك وطبيعة الحالة وموقعك بدقة.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup> وتحدث بوضوح، وأجب عن أسئلة الموظف، واتبع التعليمات التي يعطيك إياها.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><h2 id="الإسعاف" tabindex="-1">الإسعاف <a class="header-anchor" href="#الإسعاف" aria-label="Permalink to &quot;الإسعاف&quot;">​</a></h2><p>اتصل بالرقم 999 عند وجود حالة تحتاج إلى مساعدة طبية فورية لإنقاذ الحياة، مثل السكتة الدماغية وألم الصدر والحساسية الشديدة والنوبات التشنجية وصعوبة التنفس.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup> وتذكر مؤسسة حمد الطبية أن من لا تهدد حالتهم الحياة ينبغي ألا يتصلوا بالرقم 999، وأن عليهم التوجه إلى الرعاية العاجلة إذا لم تكن الحالة تحتمل الانتظار.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4]</a></sup></p><h2 id="إذا-كنت-من-الصم" tabindex="-1">إذا كنت من الصم <a class="header-anchor" href="#إذا-كنت-من-الصم" aria-label="Permalink to &quot;إذا كنت من الصم&quot;">​</a></h2><p>توفر وزارة الداخلية خدمة الطوارئ للصم على الرقم 992 على مدار الساعة، وتقصرها صفحة الوزارة على المستخدمين الصم.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> ويمكنك الوصول إليها بثلاث طرق:</p><ul><li>مكالمة فيديو إلى الرقم 992 من الحاسوب أو الهاتف المحمول.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>رسالة نصية إلى الرقم 992.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>بريد إلكتروني إلى <a href="mailto:992@moi.gov.qa" target="_blank" rel="noreferrer">992@moi.gov.qa</a>.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li></ul><p>في الرسالة النصية اذكر بوضوح نوع المشكلة والخدمة المطلوبة، مثل الإسعاف أو الدفاع المدني أو الشرطة، إضافة إلى اسمك وعنوانك وأي إصابات أو وفيات.<sup class="footnote-ref"><a href="#fn5" id="fnref5:4">[5]</a></sup> وقد تتأخر الرسائل النصية بسبب شبكة الهاتف، فلا تعتمد عليها وحدها، وتأكد من وصول رسالتك بالتواصل مع الشرطة.<sup class="footnote-ref"><a href="#fn5" id="fnref5:5">[5]</a></sup> وقد يعرّض سوء استخدام الخدمة صاحبه للمساءلة القانونية.<sup class="footnote-ref"><a href="#fn5" id="fnref5:6">[5]</a></sup></p><h2 id="أين-تجد-رعاية-الطوارئ" tabindex="-1">أين تجد رعاية الطوارئ <a class="header-anchor" href="#أين-تجد-رعاية-الطوارئ" aria-label="Permalink to &quot;أين تجد رعاية الطوارئ&quot;">​</a></h2><p>في الحالات التي تهدد الحياة اتصل بالرقم 999 أو توجه إلى أقرب قسم طوارئ تابع لمؤسسة حمد الطبية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li><strong>البالغون:</strong> مركز الإصابات والطوارئ في مستشفى حمد العام، ومستشفى الوكرة، ومستشفى الخور، ومستشفى حزم مبيريك العام، ومستشفى عائشة بنت حمد العطية، والمستشفى الكوبي.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li><strong>طوارئ النساء والولادة:</strong> مركز صحة المرأة والأبحاث.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li><strong>الأطفال دون 14 عامًا:</strong> مراكز طوارئ الأطفال في السد والمطار والريان والوكرة والخور ومستشفى عائشة بنت حمد العطية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li><strong>الحالات العاجلة غير المهددة للحياة:</strong> تدير مؤسسة الرعاية الصحية الأولية 16 وحدة للرعاية العاجلة تعمل على مدار الساعة طوال أيام الأسبوع، دون حاجة إلى موعد.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li></ul><p>إذا لم تكن متأكدًا إلى أين تذهب، فاتصل بالرقم 16000. اختر 2 ثم 2 للاستشارة العاجلة لدى مؤسسة الرعاية الصحية الأولية، أو 3 ثم 1 للاستشارة العاجلة لدى مؤسسة حمد الطبية، وهي متاحة من 8 صباحًا إلى 3 عصرًا من الأحد إلى الخميس.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><h2 id="بعد-الحادث-المروري" tabindex="-1">بعد الحادث المروري <a class="header-anchor" href="#بعد-الحادث-المروري" aria-label="Permalink to &quot;بعد الحادث المروري&quot;">​</a></h2><p>إذا أصيب أحد إصابة خطيرة فاتصل بالرقم 999 لطلب الإسعاف.<sup class="footnote-ref"><a href="#fn4" id="fnref4:3">[4]</a></sup></p><p>وفي الحوادث البسيطة بين مركبتين يمكنك تسجيل الحادث عبر تطبيق مطراش2 بدلًا من مراجعة التحقيق المروري حضوريًا:<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><ol><li>التقط ما لا يزيد على 4 صور لكل مركبة، تُظهر إحداها رقم اللوحة بوضوح.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></li><li>أبعد المركبتين عن موقع الحادث وأوقفهما بعيدًا عن الطريق.<sup class="footnote-ref"><a href="#fn6" id="fnref6:2">[6]</a></sup></li><li>فعّل خدمات الموقع في هاتفك.<sup class="footnote-ref"><a href="#fn6" id="fnref6:3">[6]</a></sup></li><li>في مطراش2 افتح خدمات المرور، ثم تقرير الحادث.<sup class="footnote-ref"><a href="#fn6" id="fnref6:4">[6]</a></sup></li><li>أدخل بيانات المركبتين: رقم المركبة ورقم البطاقة الشخصية ورقم الهاتف.<sup class="footnote-ref"><a href="#fn6" id="fnref6:5">[6]</a></sup></li><li>أرفق الصور، وأكد صحة البيانات، ثم أرسل الطلب.<sup class="footnote-ref"><a href="#fn6" id="fnref6:6">[6]</a></sup></li><li>انتظر الرسائل النصية. بعد مراجعة محققي المرور للصور يُطلب من الطرفين التوجه إلى شركة التأمين أو تصلهما الموافقة على الإصلاح.<sup class="footnote-ref"><a href="#fn6" id="fnref6:7">[6]</a></sup></li></ol><p>وتدرج وزارة الداخلية طباعة تقارير الحوادث المرورية ضمن خدماتها المرورية، لتسهيل إصلاح المركبات المتضررة.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><h2 id="طوارئ-الكهرباء-والماء" tabindex="-1">طوارئ الكهرباء والماء <a class="header-anchor" href="#طوارئ-الكهرباء-والماء" aria-label="Permalink to &quot;طوارئ الكهرباء والماء&quot;">​</a></h2><p>تعد كهرماء الحالة طارئة إذا انقطعت الكهرباء أو الماء عن منزلك دون إشعار مسبق منها.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup> اتصل بالرقم 991 في أي وقت، أو راسل <a href="mailto:991@km.com.qa" target="_blank" rel="noreferrer">991@km.com.qa</a>.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup> وجهز رقم حساب الكهرباء والماء، فنظام الهاتف يحتاج إليه.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></p><h2 id="قائمة-سريعة" tabindex="-1">قائمة سريعة <a class="header-anchor" href="#قائمة-سريعة" aria-label="Permalink to &quot;قائمة سريعة&quot;">​</a></h2><ul><li><strong>999:</strong> طوارئ الشرطة والحرائق والحالات الطبية.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li><strong>992:</strong> خدمة الطوارئ للصم.<sup class="footnote-ref"><a href="#fn5" id="fnref5:7">[5]</a></sup></li><li><strong>991:</strong> طوارئ الكهرباء والماء لدى كهرماء.<sup class="footnote-ref"><a href="#fn9" id="fnref9:1">[9]</a></sup></li><li><strong>4439 6066:</strong> الخط الساخن لمراكز طوارئ الأطفال، على مدار الساعة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li><strong>16000:</strong> خط المساعدة الصحية الوطني.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li><li><strong>107:</strong> مؤسسة الرعاية الصحية الأولية، ومنها المواعيد العاجلة أو في اليوم نفسه.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li><li><strong>16060:</strong> مركز نسمعك لاتصالات المرضى في مؤسسة حمد الطبية، على مدار الساعة.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></li></ul><p>انظر أيضًا: <a href="./health">الرعاية الصحية والتأمين</a>، <a href="./metrash">مطراش</a>، <a href="./driving">القيادة</a>، <a href="./housing-and-utilities">السكن والخدمات</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>مؤسسة حمد الطبية، <a href="https://www.hamad.qa/EN/Hospitals-and-services/Emergency-Care-Services/Pages/Emergency-and-Urgent-Care-Services.aspx" target="_blank" rel="noreferrer">خدمات الطوارئ والرعاية العاجلة</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/UNCCPCJDoha/English/Emergency_Services.html" target="_blank" rel="noreferrer">خدمات الطوارئ (999 و992)</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>مؤسسة حمد الطبية، <a href="https://www.hamad.qa/EN/Hospitals-and-services/Ambulance-Service/Rescue-Process/Pages/default.aspx" target="_blank" rel="noreferrer">إجراءات الإنقاذ</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>مؤسسة حمد الطبية، <a href="https://hamad.qa/EN/Emergency/Pages/Life-ThreateningMedicalEmergency.aspx" target="_blank" rel="noreferrer">الحالات الطبية المهددة للحياة</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/infocenter/emerservicedeaf" target="_blank" rel="noreferrer">خدمة الطوارئ للصم</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/gatraffic/!ut/p/z1/jY_NDoIwEIQfqdOCpBxrNfwUbQytwF5MT4ZE0YPx-SXEq5U9zSbfzGQYsZ7RFN7jNbzGxxRu8z9QdjnmUDy3MNapWe6Ls9epFMgF6xagUjItObiRJSRU62q3tVoAnNEaP36cwjp_BKB4fMdoQepyVyFpYYomS-YFzUELfQLk5gvEJv4red697zFWH0zJlfc!/?1dmy=&amp;urile=wcm:path:/wcmlib-internet-en/sa-departmentcommittee/generaladministrationoftraffic/minor+accident" target="_blank" rel="noreferrer">تسجيل الحوادث البسيطة عبر مطراش2</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/trafficservices" target="_blank" rel="noreferrer">خدمات المرور</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn8" class="footnote-item"><p>كهرماء، <a href="https://www.km.qa/CustomerService/Pages/ServiceDetails.aspx?ItemID=28" target="_blank" rel="noreferrer">مشكلات الطوارئ والخدمة</a>. آخر تحقق: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn9" class="footnote-item"><p>كهرماء، <a href="https://km.qa/Pages/call-center.aspx?IsDlg=1" target="_blank" rel="noreferrer">مركز الاتصال 991</a>. آخر تحقق: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref9:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn10" class="footnote-item"><p>مؤسسة الرعاية الصحية الأولية، <a href="https://www.phcc.gov.qa/patients-clients/eservice-guestpage/register-new-health-card" target="_blank" rel="noreferrer">الحصول على بطاقة صحية جديدة</a>. آخر تحقق: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn11" class="footnote-item"><p>مؤسسة حمد الطبية، <a href="https://hamad.qa/EN/news/2025/March/Pages/Easier-Than-Ever-to-Manage-Your-Specialist-Appointment.aspx" target="_blank" rel="noreferrer">إدارة مواعيد العيادات التخصصية</a>. آخر تحقق: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',28)])])}const b=a(s,[["render",t]]);export{u as __pageData,b as default};
